class DatabaseOpenError(Exception):
    """数据库文件无法打开（如父目录不存在或路径指向一个目录）。"""


def connect(db_path):
    """打开（必要时创建）数据库并确保工单表存在。

    仅在打开数据库文件这一步失败时抛出 DatabaseOpenError；
    建表等后续 SQL 执行的异常不在此转换，按原样抛出。
